//! Versioned QUIC handshake profiles. The TLS transcript is generated by
//! craftls, not rewritten after encryption. Quinn still owns ACKs, loss
//! recovery, congestion control and packet numbers.
//!
//! Chrome115 is an explicit baseline, not a claim to reproduce every future
//! Chrome release or the application's HTTP/3 traffic.

use std::{any::Any, io::Cursor, sync::Arc, time::Duration};

use anyhow::{Result, ensure};
use bytes::BytesMut;
use craft_tls::rustls as tls;
use quinn_proto::{
    ConnectError, ConnectionId, Side, TransportError, TransportErrorCode,
    crypto::{self, CryptoError, ExportKeyingMaterialError, HeaderKey, KeyPair, Keys},
    transport_parameters::TransportParameters,
};
use rand::{Rng, seq::SliceRandom};

pub(super) const PROFILE: &str = "chrome115";

pub(super) fn is_chrome(name: &str) -> bool {
    name == "chrome" || name == PROFILE
}

pub(super) fn endpoint_config() -> quinn::EndpointConfig {
    let mut config = quinn::EndpointConfig::default();
    config.cid_generator(|| Box::new(quinn_proto::RandomConnectionIdGenerator::new(0)));
    config
        .max_udp_payload_size(1472)
        .expect("valid QUIC receive MTU");
    config.grease_quic_bit(false);
    config
}

pub(super) fn transport_config(transport: &mut quinn::TransportConfig) {
    // Advertised limits must match the transport's actual accounting.
    transport.receive_window(quinn::VarInt::from_u32(15 * 1024 * 1024));
    transport.stream_receive_window(quinn::VarInt::from_u32(6 * 1024 * 1024));
    transport.max_concurrent_bidi_streams(100u32.into());
    transport.max_concurrent_uni_streams(103u32.into());
    transport.max_idle_timeout(Some(Duration::from_secs(30).try_into().unwrap()));
    // Keep burst buffering large; matching a single frame's advertised maximum
    // must not shrink the total receive queue and reintroduce video loss.
    transport.datagram_receive_buffer_size(Some(2 * 1024 * 1024));
    transport.allow_spin(false);
    transport.ack_frequency_config(None);
}

pub(super) fn client_config(
    skip_verify: bool,
    alpn: &[String],
    pin: Option<[u8; 32]>,
) -> Result<quinn::ClientConfig> {
    ensure!(alpn == ["h3"], "Chrome QUIC fingerprint requires ALPN h3");
    let builder = tls::ClientConfig::builder_with_protocol_versions(&[&tls::version::TLS13]);
    let config = if skip_verify || pin.is_some() {
        builder
            .dangerous()
            .with_custom_certificate_verifier(Arc::new(ProfileVerifier { pin }))
            .with_no_client_auth()
    } else {
        builder
            .with_root_certificates(super::transport::get_root_cert_store().clone())
            .with_no_client_auth()
    };
    let mut config = config.with_fingerprint(
        tls::craft::CHROME_115_QUIC
            .builder()
            .preserve_protocol_versions(),
    );
    // No PSK or 0-RTT: these need a separate captured/resumed profile and
    // authenticated ALPS/transport-parameter state. Never forge PSK binders.
    config.resumption = tls::client::Resumption::disabled();
    config.enable_early_data = false;
    let mut config = quinn::ClientConfig::new(Arc::new(ProfileCrypto(Arc::new(config))));
    config.initial_dst_cid_provider(Arc::new(|| {
        let id: [u8; 8] = rand::random();
        ConnectionId::new(&id)
    }));
    Ok(config)
}

struct ProfileCrypto(Arc<tls::ClientConfig>);
impl crypto::ClientConfig for ProfileCrypto {
    fn start_session(
        self: Arc<Self>,
        version: u32,
        server_name: &str,
        params: &TransportParameters,
    ) -> Result<Box<dyn crypto::Session>, ConnectError> {
        if version != 1 {
            return Err(crypto::UnsupportedVersion.into());
        }
        let mut wire = Vec::new();
        params.write(&mut wire);
        let wire = chrome_parameters(&wire).map_err(|_| {
            ConnectError::InvalidServerName("QUIC profile parameter mismatch".into())
        })?;
        let conn = tls::quic::ClientConnection::new(
            self.0.clone(),
            tls::quic::Version::V1,
            rustls_pki_types::ServerName::try_from(server_name)
                .map_err(|_| ConnectError::InvalidServerName("invalid TLS server name".into()))?
                .to_owned(),
            wire,
        )
        .map_err(|_| ConnectError::InvalidServerName("invalid QUIC TLS configuration".into()))?;
        Ok(Box::new(ProfileSession {
            inner: tls::quic::Connection::Client(conn),
            ready: false,
            next: None,
        }))
    }
}

/// Reorder/extend actual parameters, never invent flow-control credit. Omit
/// only negotiated features or parameters with the RFC's default value.
fn chrome_parameters(input: &[u8]) -> Result<Vec<u8>> {
    let mut parameters = parse_parameters(input)?;
    let expected = [
        (1, 30000),
        (3, 1472),
        (4, 15728640),
        (5, 6291456),
        (6, 6291456),
        (7, 6291456),
        (8, 100),
        (9, 103),
    ];
    for (id, value) in expected {
        ensure!(
            parameters
                .iter()
                .any(|(k, v)| *k == id && read_varint(&mut &v[..]).ok() == Some(value)),
            "QUIC profile transport limits mismatch"
        );
    }
    ensure!(
        parameters.iter().any(|(k, v)| *k == 15 && v.is_empty()),
        "QUIC profile requires zero-length source CID"
    );
    parameters.retain(|(id, value)| match *id {
        // min_ack_delay / grease_quic_bit are optional negotiated features;
        // not advertising them prevents the peer from using them.
        0xff04de1b | 0x2ab2 => false,
        // Drop Quinn's reserved parameter and supply Chrome's fresh GREASE.
        id if id % 31 == 27 => false,
        10 if value == &[3] => false,
        11 if value == &[25] => false,
        14 if value == &[2] => false,
        _ => true,
    });
    // QUIC DATAGRAM's wire length includes frame overhead. The endpoint
    // receive MTU caps actual frames below this value in either case.
    if let Some((_, value)) = parameters.iter_mut().find(|(id, _)| *id == 0x20) {
        *value = varint(65536);
    }
    let mut rng = rand::rng();
    let grease_version = rng.random::<u32>() & 0xf0f0f0f0 | 0x0a0a0a0a;
    let mut versions = 1u32.to_be_bytes().to_vec();
    versions.extend_from_slice(&grease_version.to_be_bytes());
    versions.extend_from_slice(&1u32.to_be_bytes());
    parameters.push((0xff73db, versions));
    parameters.push((0x4752, 1u32.to_be_bytes().to_vec()));
    parameters.push((0x3128, b"RVCM".to_vec()));
    let mut grease = vec![0; rng.random_range(0..=16)];
    rng.fill(grease.as_mut_slice());
    parameters.push((31 * rng.random_range(0..(1u64 << 30)) + 27, grease));
    parameters.shuffle(&mut rng);
    let mut wire = Vec::new();
    for (id, value) in parameters {
        wire.extend(varint(id));
        wire.extend(varint(value.len() as u64));
        wire.extend(value);
    }
    // Let Quinn's own RFC parser validate the outgoing profile, too.
    TransportParameters::read(Side::Server, &mut Cursor::new(&wire))?;
    Ok(wire)
}

fn read_varint(input: &mut &[u8]) -> Result<u64> {
    ensure!(!input.is_empty(), "truncated QUIC variable integer");
    let n = 1usize << (input[0] >> 6);
    ensure!(input.len() >= n, "truncated QUIC variable integer");
    let mut value = u64::from(input[0] & 63);
    for b in &input[1..n] {
        value = (value << 8) | u64::from(*b);
    }
    *input = &input[n..];
    Ok(value)
}
fn varint(value: u64) -> Vec<u8> {
    let mut wire = Vec::new();
    quinn::VarInt::from_u64(value)
        .expect("bounded QUIC profile parameter")
        .into_inner();
    if value < 64 {
        wire.push(value as u8);
    } else if value < 16384 {
        wire.extend_from_slice(&((value as u16) | 0x4000).to_be_bytes());
    } else if value < (1 << 30) {
        wire.extend_from_slice(&((value as u32) | 0x80000000).to_be_bytes());
    } else {
        wire.extend_from_slice(&(value | 0xc000000000000000).to_be_bytes());
    }
    wire
}
fn parse_parameters(mut input: &[u8]) -> Result<Vec<(u64, Vec<u8>)>> {
    let mut output = Vec::new();
    while !input.is_empty() {
        let id = read_varint(&mut input)?;
        let len = usize::try_from(read_varint(&mut input)?)?;
        ensure!(input.len() >= len, "truncated QUIC parameter");
        ensure!(
            !output.iter().any(|(old, _)| *old == id),
            "duplicate QUIC parameter"
        );
        output.push((id, input[..len].to_vec()));
        input = &input[len..];
    }
    Ok(output)
}

struct ProfileSession {
    inner: tls::quic::Connection,
    ready: bool,
    next: Option<tls::quic::Secrets>,
}
fn initial_suite() -> &'static tls::Tls13CipherSuite {
    tls::crypto::ring::cipher_suite::TLS13_AES_128_GCM_SHA256
        .tls13()
        .unwrap()
}
impl ProfileSession {
    fn suite(&self) -> &'static tls::Tls13CipherSuite {
        self.inner
            .negotiated_cipher_suite()
            .and_then(|s| s.tls13())
            .unwrap_or_else(initial_suite)
    }
}
impl crypto::Session for ProfileSession {
    fn initial_keys(&self, cid: &ConnectionId, side: Side) -> Keys {
        let suite = initial_suite();
        let side = match side {
            Side::Client => tls::Side::Client,
            Side::Server => tls::Side::Server,
        };
        wrap_keys(
            tls::quic::Keys::initial(
                tls::quic::Version::V1,
                suite,
                suite.quic.unwrap(),
                cid,
                side,
            ),
            suite,
        )
    }
    fn handshake_data(&self) -> Option<Box<dyn Any>> {
        self.ready.then(|| {
            Box::new(quinn::crypto::rustls::HandshakeData {
                protocol: self.inner.alpn_protocol().map(Vec::from),
                server_name: None,
            }) as Box<dyn Any>
        })
    }
    fn peer_identity(&self) -> Option<Box<dyn Any>> {
        self.inner.peer_certificates().map(|certs| {
            Box::new(
                certs
                    .iter()
                    .map(|cert| cert.clone().into_owned())
                    .collect::<Vec<_>>(),
            ) as Box<dyn Any>
        })
    }
    fn early_crypto(&self) -> Option<(Box<dyn HeaderKey>, Box<dyn crypto::PacketKey>)> {
        None
    }
    fn early_data_accepted(&self) -> Option<bool> {
        Some(false)
    }
    fn is_handshaking(&self) -> bool {
        self.inner.is_handshaking()
    }
    fn read_handshake(&mut self, buf: &[u8]) -> Result<bool, TransportError> {
        self.inner
            .read_hs(buf)
            .map_err(|e| match self.inner.alert() {
                Some(alert) => TransportError {
                    code: TransportErrorCode::crypto(alert.get_u8()),
                    frame: None,
                    reason: e.to_string(),
                },
                None => TransportError {
                    code: TransportErrorCode::PROTOCOL_VIOLATION,
                    frame: None,
                    reason: format!("TLS error: {e}"),
                },
            })?;
        if !self.ready && (self.inner.alpn_protocol().is_some() || !self.inner.is_handshaking()) {
            self.ready = true;
            return Ok(true);
        }
        Ok(false)
    }
    fn transport_parameters(&self) -> Result<Option<TransportParameters>, TransportError> {
        self.inner
            .quic_transport_parameters()
            .map(|params| {
                TransportParameters::read(Side::Client, &mut Cursor::new(params))
                    .map_err(Into::into)
            })
            .transpose()
    }
    fn write_handshake(&mut self, output: &mut Vec<u8>) -> Option<Keys> {
        let keys = match self.inner.write_hs(output)? {
            tls::quic::KeyChange::Handshake { keys } => keys,
            tls::quic::KeyChange::OneRtt { keys, next } => {
                self.next = Some(next);
                keys
            }
        };
        Some(wrap_keys(keys, self.suite()))
    }
    fn next_1rtt_keys(&mut self) -> Option<KeyPair<Box<dyn crypto::PacketKey>>> {
        let suite = self.suite();
        let keys = self.next.as_mut()?.next_packet_keys();
        Some(KeyPair {
            local: Box::new(Packet(keys.local, suite)),
            remote: Box::new(Packet(keys.remote, suite)),
        })
    }
    fn is_valid_retry(&self, cid: &ConnectionId, header: &[u8], payload: &[u8]) -> bool {
        use aes_gcm::{Aes128Gcm, KeyInit, aead::AeadInPlace};
        let Some(n) = payload.len().checked_sub(16) else {
            return false;
        };
        let mut pseudo = vec![cid.len() as u8];
        pseudo.extend_from_slice(cid);
        pseudo.extend_from_slice(header);
        pseudo.extend_from_slice(&payload[..n]);
        // RFC 9001 section 5.8: public, fixed Retry-integrity key and nonce.
        let key = Aes128Gcm::new_from_slice(&[
            0xbe, 0x0c, 0x69, 0x0b, 0x9f, 0x66, 0x57, 0x5a, 0x1d, 0x76, 0x6b, 0x54, 0xe3, 0x68,
            0xc8, 0x4e,
        ])
        .unwrap();
        key.decrypt_in_place_detached(
            (&[
                0x46, 0x15, 0x99, 0xd3, 0x5d, 0x63, 0x2b, 0xf2, 0x23, 0x98, 0x25, 0xbb,
            ])
                .into(),
            &pseudo,
            &mut [],
            payload[n..].into(),
        )
        .is_ok()
    }
    fn export_keying_material(
        &self,
        output: &mut [u8],
        label: &[u8],
        context: &[u8],
    ) -> Result<(), ExportKeyingMaterialError> {
        self.inner
            .export_keying_material(output, label, Some(context))
            .map_err(|_| ExportKeyingMaterialError)?;
        Ok(())
    }
}
fn wrap_keys(keys: tls::quic::Keys, suite: &'static tls::Tls13CipherSuite) -> Keys {
    Keys {
        header: KeyPair {
            local: Box::new(Header(keys.local.header)),
            remote: Box::new(Header(keys.remote.header)),
        },
        packet: KeyPair {
            local: Box::new(Packet(keys.local.packet, suite)),
            remote: Box::new(Packet(keys.remote.packet, suite)),
        },
    }
}
struct Header(Box<dyn tls::quic::HeaderProtectionKey>);
impl Header {
    fn apply(&self, offset: usize, packet: &mut [u8], encrypt: bool) {
        let (header, sample) = packet.split_at_mut(offset + 4);
        let (first, rest) = header.split_at_mut(1);
        let end = (offset + 3).min(rest.len());
        let pn = &mut rest[offset - 1..end];
        let result = if encrypt {
            self.0
                .encrypt_in_place(&sample[..self.0.sample_len()], &mut first[0], pn)
        } else {
            self.0
                .decrypt_in_place(&sample[..self.0.sample_len()], &mut first[0], pn)
        };
        // Quinn guarantees the sample and PN bounds before calling HeaderKey.
        debug_assert!(result.is_ok());
    }
}
impl HeaderKey for Header {
    fn encrypt(&self, offset: usize, packet: &mut [u8]) {
        self.apply(offset, packet, true);
    }
    fn decrypt(&self, offset: usize, packet: &mut [u8]) {
        self.apply(offset, packet, false);
    }
    fn sample_size(&self) -> usize {
        self.0.sample_len()
    }
}
struct Packet(
    Box<dyn tls::quic::PacketKey>,
    &'static tls::Tls13CipherSuite,
);
impl crypto::PacketKey for Packet {
    fn encrypt(&self, packet: u64, buf: &mut [u8], header_len: usize) {
        let (header, payload) = buf.split_at_mut(header_len);
        let (data, tag) = payload.split_at_mut(payload.len() - self.0.tag_len());
        let auth = self
            .0
            .encrypt_in_place(packet, header, data)
            .expect("QUIC packet below AEAD size limit");
        tag.copy_from_slice(auth.as_ref());
    }
    fn decrypt(
        &self,
        packet: u64,
        header: &[u8],
        payload: &mut BytesMut,
    ) -> Result<(), CryptoError> {
        let len = self
            .0
            .decrypt_in_place(packet, header, payload)
            .map_err(|_| CryptoError)?
            .len();
        payload.truncate(len);
        Ok(())
    }
    fn tag_len(&self) -> usize {
        self.0.tag_len()
    }
    fn confidentiality_limit(&self) -> u64 {
        self.1.common.confidentiality_limit
    }
    fn integrity_limit(&self) -> u64 {
        self.1.common.integrity_limit
    }
}

#[derive(Debug)]
struct ProfileVerifier {
    pin: Option<[u8; 32]>,
}
impl tls::client::danger::ServerCertVerifier for ProfileVerifier {
    fn verify_server_cert(
        &self,
        cert: &rustls_pki_types::CertificateDer<'_>,
        _: &[rustls_pki_types::CertificateDer<'_>],
        _: &rustls_pki_types::ServerName<'_>,
        _: &[u8],
        _: rustls_pki_types::UnixTime,
    ) -> Result<tls::client::danger::ServerCertVerified, tls::Error> {
        if let Some(pin) = self.pin {
            use sha2::{Digest, Sha256};
            if Sha256::digest(cert.as_ref()).as_slice() != pin {
                return Err(tls::Error::General("QUIC certificate pin mismatch".into()));
            }
        }
        Ok(tls::client::danger::ServerCertVerified::assertion())
    }
    fn verify_tls12_signature(
        &self,
        msg: &[u8],
        cert: &rustls_pki_types::CertificateDer<'_>,
        signature: &tls::DigitallySignedStruct,
    ) -> Result<tls::client::danger::HandshakeSignatureValid, tls::Error> {
        tls::crypto::verify_tls12_signature(
            msg,
            cert,
            signature,
            &tls::crypto::ring::default_provider().signature_verification_algorithms,
        )
    }
    fn verify_tls13_signature(
        &self,
        msg: &[u8],
        cert: &rustls_pki_types::CertificateDer<'_>,
        signature: &tls::DigitallySignedStruct,
    ) -> Result<tls::client::danger::HandshakeSignatureValid, tls::Error> {
        tls::crypto::verify_tls13_signature(
            msg,
            cert,
            signature,
            &tls::crypto::ring::default_provider().signature_verification_algorithms,
        )
    }
    fn supported_verify_schemes(&self) -> Vec<tls::SignatureScheme> {
        tls::crypto::ring::default_provider()
            .signature_verification_algorithms
            .supported_schemes()
    }
}

